const input = $input.item.json;
const body = input.body || input;
const overrideDest = body.destination || body.country || body.dest || '';


if (overrideDest) {
  const destConfig = {
    'كازاخستان': { gradient: 'linear-gradient(180deg,#2980b9,#1a5276 40%,#0f1a2e)', ua: true, en: 'Kazakhstan' },
    'روسيا':     { gradient: 'linear-gradient(180deg,#1a2744,#162038 40%,#0f1a2e)', ua: false, en: 'Russia' },
    'بولندا':    { gradient: 'linear-gradient(180deg,#1a6b3c,#1a3c34 40%,#0f1a2e)', ua: true, en: 'Poland' },
    'أوزبكستان': { gradient: 'linear-gradient(180deg,#4a2366,#2c1a44 40%,#0f1a2e)', ua: true, en: 'Uzbekistan' },
  };
  const cfg = destConfig[overrideDest] || destConfig['كازاخستان'];
  return [{ json: {
    destination: overrideDest,
    content_type: 'scenic',
    badge: '📸 Fal Poster',
    gradient: cfg.gradient,
    show_ua_phone: cfg.ua,
    platform: 'instagram',
    dest_en: cfg.en,
  }}];
}

const schedule = [
  { day: 6, destination: 'كازاخستان', content_type: 'offer',       badge: '💰 عرض خاص'            },
  { day: 0, destination: 'روسيا',     content_type: 'did_you_know', badge: '🧠 هل تعلم؟'            },
  { day: 1, destination: 'بولندا',    content_type: 'travel_tip',   badge: '✈️ نصيحة سفر'           },
  { day: 2, destination: 'أوزبكستان', content_type: 'scenic',       badge: '📸 جمال الطبيعة'         },
  { day: 3, destination: 'كازاخستان', content_type: 'offer',        badge: '💰 عرض خاص'            },
  { day: 4, destination: 'كازاخستان', content_type: 'interactive',  badge: '💬 سؤال للجمهور'         },
  { day: 5, destination: 'روسيا',     content_type: 'services',     badge: '🌟 خدماتنا'             },
];

const inp = $input.item.json.body || $input.item.json;
const overrideCountry = inp.destination || inp.country || inp.dest || '';
if (overrideCountry) {
  const cfg = destConfig[overrideCountry] || destConfig['كازاخستان'];
  return [{ json: {
    destination: overrideCountry,
    content_type: inp.content_type || 'scenic',
    badge: inp.badge || '📸 بوستر Fal',
    gradient: cfg.gradient,
    show_ua_phone: cfg.ua,
    platform: 'instagram',
  }}];
}

const today = new Date().getDay();
const slot = schedule.find(s => s.day === today) || schedule[0];

// Destinations config
const destConfig = {
  'كازاخستان': { gradient: 'linear-gradient(180deg,#2980b9,#1a5276 40%,#0f1a2e)', ua: true  },
  'روسيا':     { gradient: 'linear-gradient(180deg,#1a2744,#162038 40%,#0f1a2e)', ua: false },
  'بولندا':    { gradient: 'linear-gradient(180deg,#1a6b3c,#1a3c34 40%,#0f1a2e)', ua: true  },
  'أوزبكستان': { gradient: 'linear-gradient(180deg,#4a2366,#2c1a44 40%,#0f1a2e)', ua: true  },
};
const cfg = destConfig[slot.destination] || destConfig['كازاخستان'];

return [{ json: {
  destination: slot.destination,
  content_type: slot.content_type,
  badge: slot.badge,
  gradient: cfg.gradient,
  show_ua_phone: cfg.ua,
  platform: 'instagram',
}}];

const raw = $input.item.json.text || $input.item.json.response || '';
let d = {};
try { const m = raw.match(/\{[\s\S]*\}/); if(m) d = JSON.parse(m[0]); } catch(e) {}

const pick = $('Pick Destination & Type').item.json;
const dest = d.destination || pick.destination || 'كازاخستان';
const mode = d.mode || 'discovery';

return [{ json: {
  destination:  dest,
  mode:         mode,
  title:        d.title        || dest,
  subtitle:     d.subtitle     || '',
  highlight:    (mode === 'luxury' || mode === 'hook') ? '' : (d.highlight || ''),
  price:        mode === 'offer' ? (d.price || '') : '',
  cta:          (mode === 'info' || (mode === 'luxury' && !d.cta)) ? '' : (d.cta || ''),
  caption_ar:   d.caption_ar   || '',
  hashtags:     d.hashtags     || '',
  country:      pick.dest_en   || 'Destination',
  image_prompt: d.image_prompt || ('Ultra realistic cinematic ' + (pick.dest_en||'destination') + ' landscape, golden hour, 8K, no text, no watermark'),
}}];

const p = $input.item.json;
let prompt = p.image_prompt || '';
const kws = ['ultra realistic','8k','no text','no watermark'];
kws.forEach(k=>{ if(!prompt.toLowerCase().includes(k.replace(' ',''))) prompt+=', '+k; });
if(prompt.split(' ').length < 20)
  prompt += ', cinematic lighting, golden hour, wide angle, sharp details, professional travel photography';

// Mode-based prompt enhancement
const mode = p.mode || 'discovery';
const modeExtra = {
  offer:     ', vibrant colors, energetic atmosphere, sunny bright',
  discovery: ', mysterious atmosphere, dreamy light, breathtaking view',
  info:      ', clear daylight, sharp architectural details, informative scene',
  hook:      ', surprising unusual angle, dramatic composition, eye-catching',
  luxury:    ', ultra premium minimalist, perfect composition, magazine cover quality'
};
if(modeExtra[mode]) prompt += modeExtra[mode];

return [{ json: { ...p, image_prompt: prompt.trim() } }];

const p = $('Build Image Prompt').item.json;
const fal = $input.item.json;
const url = fal.image_url;
if (!url) throw new Error('No Fal image_url');
const lines = [
  p.title ? '🖼️ <b>' + p.title + '</b>' : '',
  p.subtitle || '',
  p.highlight ? '✨ ' + p.highlight : '',
  p.price ? '💰 ' + p.price : '',
  p.cta ? '👉 ' + p.cta : '',
  '',
  p.caption_ar || '',
  p.hashtags || ''
].filter(Boolean);
return [{ json: {
  chat_id: 493831958,
  photo: url,
  caption: lines.join('\n'),
  destination: p.destination,
  mode: p.mode || 'discovery'
}}];

const prep = $('Build Image Prompt').item.json;
const fal = $input.item.json;
const caption = ((prep.caption_ar || '') + '\n\n' + (prep.hashtags || '')).trim();
return [{ json: {
  image_url: fal.image_url,
  caption: caption.slice(0, 1024),
  chat_id: 493831958,
  destination: prep.destination,
  title: prep.title || prep.destination,
  ok: !!fal.image_url
}}];
